css:
.dcw-split.is-even { grid-template-columns: 1fr 1fr; align-items: end; margin-bottom: 8px; }
.dcw-fig { display: flex; flex-direction: column; min-width: 0; }
.dcw-fig-cap { margin-top: 14px; }
.dcw-fig-num { margin-bottom: 3px; color: #5f5f5f; font-family: Inconsolata, monospace; font-size: 12px; }
.dcw-screens { display: grid; grid-template-columns: repeat(4, 1fr); grid-column-gap: clamp(16px, 2.5vw, 32px); grid-row-gap: 32px; margin-top: 28px; }
.dcw-screens.is-5 { grid-template-columns: repeat(5, 1fr); }
.dcw-goal-link { color: #0f6e68; font-size: 14px; font-weight: 600; text-decoration: none; }
.dcw-results { display: grid; grid-template-columns: 1fr 1fr; grid-column-gap: clamp(20px, 3vw, 32px); grid-row-gap: 20px; margin-top: 20px; }
.dcw-res-card { padding: clamp(20px, 3vw, 32px); border: 1px solid #e2e2e2; border-radius: 16px; background-color: #ffffff; }
.dcw-res-card.is-wins { border-color: transparent; background-image: linear-gradient(160deg, #e3f2ef, #d4ece6); }
.dcw-res-h { display: flex; align-items: center; grid-column-gap: 8px; margin-bottom: 14px; color: #111111; font-size: 18px; font-weight: 600; }
.dcw-res-dot { width: 10px; height: 10px; border-radius: 50%; background-color: #0f6e68; }
.dcw-res-dot.is-open { border: 2px solid #0f6e68; background-color: transparent; }
.dcw-callout { display: flex; align-items: center; grid-column-gap: 12px; margin-top: 18px; padding: 12px 16px; border-radius: 12px; background-color: #062b2a; }
.dcw-callout-num { flex: none; color: #6fd9cb; font-size: 24px; font-weight: 700; white-space: nowrap; }
.dcw-callout-text { color: rgba(255,255,255,0.85); font-size: 15px; line-height: 1.4; }
.dcw-decision { display: grid; grid-template-columns: 5fr 6fr; grid-column-gap: clamp(28px, 5vw, 72px); grid-row-gap: 28px; margin-top: clamp(40px, 5vw, 64px); padding-top: clamp(40px, 5vw, 64px); border-top: 1px solid #e2e2e2; }
.dcw-decision-title { margin-top: 0; margin-bottom: 18px; color: #111111; font-size: 20px; font-weight: 600; line-height: 1.3; }
.dcw-chain { display: flex; flex-direction: column; }
.dcw-chain-card { padding: 16px 18px; border: 1px solid #e2e2e2; border-radius: 10px; background-color: #ffffff; }
.dcw-chain-card.is-changed { border-color: transparent; background-image: linear-gradient(160deg, #0f6e68, #0a524e); }
.dcw-chain-k { margin-bottom: 6px; color: #0a524e; font-size: 11px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; }
.dcw-chain-k.is-changed { color: #bff0e8; }
.dcw-chain-p { margin-top: 0; margin-bottom: 0; color: #3d3d3d; font-size: 15px; line-height: 1.55; }
.dcw-chain-p.is-changed { color: rgba(255,255,255,0.94); }
.dcw-chain-arrow { padding-left: 18px; color: #0f6e68; font-weight: 700; line-height: 26px; }
.dcw-cmp { display: grid; grid-template-columns: repeat(2, minmax(0, 260px)); grid-column-gap: clamp(16px, 3vw, 40px); grid-row-gap: 28px; align-items: start; }
.dcw-cmp-item { display: flex; flex-direction: column; align-items: flex-start; min-width: 0; }
.dcw-cmp-label { margin-bottom: 10px; padding: 2px 0; color: #5f5f5f; font-size: 12px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }
.dcw-cmp-label.is-after { padding: 2px 8px; border-radius: 999px; background-color: #e3f2ef; color: #0f6e68; }
.dcw-sort { display: grid; grid-template-columns: repeat(3, 1fr); grid-column-gap: 12px; grid-row-gap: 12px; margin-bottom: 12px; }
.dcw-sort-col { padding: 14px; border: 1px solid #e2e2e2; border-radius: 10px; background-color: #ffffff; }
.dcw-sort-col.is-keep { border-color: #0f6e68; background-color: #e3f2ef; }
.dcw-sort-h { margin-bottom: 8px; color: #5f5f5f; font-size: 13px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; }
.dcw-sort-h.is-keep { color: #0a524e; }
.dcw-sort-item { padding-top: 6px; padding-bottom: 6px; border-top: 1px solid #e2e2e2; color: #3d3d3d; font-size: 14px; }
@media screen and (max-width: 991px) { .dcw-split.is-even { grid-template-columns: 1fr; } .dcw-decision { grid-template-columns: 1fr; } .dcw-screens { grid-template-columns: repeat(3, 1fr); } .dcw-screens.is-5 { grid-template-columns: repeat(3, 1fr); } }
@media screen and (max-width: 767px) { .dcw-results { grid-template-columns: 1fr; } .dcw-sort { grid-template-columns: 1fr; } .dcw-screens { grid-template-columns: repeat(2, 1fr); } .dcw-screens.is-5 { grid-template-columns: repeat(2, 1fr); } .dcw-cmp { grid-template-columns: repeat(2, 1fr); grid-column-gap: 14px; } }
